with valid as (select *, date_format(opened_date, 'yyyy-MM-dd') opened_date_label, lower(status) status_lower, coalesce(status, 'DIRECT') status_clean from accounts where opened_date >= to_date('2023-07-04') and customer_id is not null) select c.segment, a.account_type, count(*) as num_rows, round(avg(a.balance), 2) as avg_balance from valid a left join customers c on a.customer_id = c.id group by c.segment, a.account_type;
